static bool valid(const RunReq&r){if(r.magic!=0x33434246||!r.bytes||r.bytes>128||r.bytes%4)return false;if(r.budget>128)return false;if(r.caps&~15u)return false;u32 steps=0,wins=0,controls=0;for(u32 ip=0;ip+3<r.bytes&&steps++<r.budget;ip+=4){u8 op=r.code[ip],a=r.code[ip+1];if(op==OP_END)return wins==1&&controls>0;if(op==OP_WINDOW){if(wins||a!=1)return false;wins++;controls++;}else if(op>=OP_LABEL&&op<=OP_STATUS)controls++;else return false;}return false;}
static void copyTitle(const char*s){u32 i=0;for(;i<38&&s[i];i++)title[i]=s[i];title[i]=0;}
static u32 hashName(const char*s){u32 h=2166136261u;for(u32 i=0;s&&s[i];i++){h^=(u8)s[i];h*=16777619u;}return h?h:1u;}
