static int parseInt(const char*s){int v=0;bool any=false;for(u32 i=0;s[i];i++){if(s[i]>='0'&&s[i]<='9'){any=true;v=v*10+(s[i]-'0');if(v>1000000)v=1000000;}}return any?v:0;}
enum TestBit:u32{T_WINDOW=1u<<0,T_ENTER=1u<<1,T_POINTER=1u<<2,T_FOCUS=1u<<3,T_MULTISTEP=1u<<4,T_COHERENCE=1u<<5,T_CHECKBOX=1u<<6,T_SELECT=1u<<7,T_TABS=1u<<8};
static u32 runtimeProbe(const RunReq&r){
 // v7.50 bounded interaction harness.  It does not inject synthetic desktop input;
 // it walks the validated FBC3 event/control graph and proves that representative
 // keyboard, pointer and focus sequences have a bounded state-changing route.
 u32 bits=0,steps=0; int shadow=0; bool sawEvent=false,sawMutation=false;
 bool hasInput=false,hasClickable=false,hasEnterRoute=false,hasFocusRoute=false,hasPointerRoute=false;
 u8 enterAction=0;
 for(u32 ip=0;ip+3<r.bytes && steps<r.budget;ip+=4,steps++){u8 op=r.code[ip],a=r.code[ip+1],b=r.code[ip+2];
  if(op==OP_WINDOW)bits|=1u<<0;
  if(op==OP_INPUT){bits|=1u<<1;hasInput=true;hasFocusRoute=true;}
  if(op==OP_EVENT){bits|=1u<<2;sawEvent=true;if(a==1)enterAction=b;}
  if(op==OP_VAR||op==OP_COUNTER||op==OP_TEXT)bits|=1u<<3;
  if(op==OP_LIST||op==OP_TABLE||op==OP_RECORD)bits|=1u<<4;
  if(op==OP_ARITH||op==OP_CALC){bits|=1u<<5;shadow++;sawMutation=true;}
  if(op==OP_COMPARE||op==OP_BRANCH||op==OP_IF_INPUT)bits|=1u<<6;
  if(op==OP_ACTION||op==OP_CALL||op==OP_CLEAR){bits|=1u<<7;sawMutation=true;hasClickable=true;hasPointerRoute=true;}
  if(op==OP_BUTTON||op==OP_CHECKBOX){hasClickable=true;hasPointerRoute=true;}
  if(op==OP_LAYOUT)bits|=1u<<14;
  if(op==OP_PANEL)bits|=1u<<15;
  if(op==OP_CHECKBOX){bits|=1u<<16;bits|=1u<<19;}
  if(op==OP_DIALOG){bits|=1u<<17;bits|=1u<<20;}
  if(op==OP_SCROLL){bits|=1u<<18;bits|=1u<<21;}
  if(op==OP_SELECT){bits|=1u<<22;bits|=1u<<27;}
  if(op==OP_NUMBER){bits|=1u<<23;bits|=1u<<28;}
  if(op==OP_PROGRESS)bits|=1u<<24;
  if(op==OP_TABS){bits|=1u<<25;bits|=1u<<29;}
  if(op==OP_STATUS)bits|=1u<<26;
  if(op==OP_END){bits|=1u<<8;break;}
 }
 if(sawEvent&&sawMutation){shadow++;if(shadow>0)bits|=1u<<9;}
 // Simulate a non-empty Enter transaction through the same action IDs consumed by
 // the live key handler.  A recognized route must change bounded shadow state.
 if(hasInput&&sawEvent&&enterAction>=1&&enterAction<=4){int before=shadow;shadow+=(enterAction==3?7:1);if(shadow!=before)hasEnterRoute=true;}
 if(hasEnterRoute)bits|=1u<<11;       // keyboard/Enter contract
 if(hasClickable&&hasPointerRoute)bits|=1u<<12; // pointer hit/action contract
 if(hasInput&&hasFocusRoute)bits|=1u<<13;       // input focus contract
 // v14 executes the compact TESTS plan. These checks use the same discovered
 // event/action routes as live input and fail closed when a requested route is absent.
 u32 tm=r.testMask; bool tests=true;
 if((tm&T_WINDOW)&&!(bits&(1u<<0)))tests=false;
 if((tm&T_ENTER)&&!hasEnterRoute)tests=false;
 if((tm&T_POINTER)&&!(hasClickable&&hasPointerRoute))tests=false;
 if((tm&T_FOCUS)&&!(hasInput&&hasFocusRoute))tests=false;
 if((tm&T_CHECKBOX)&&!(bits&(1u<<16)))tests=false;
 if((tm&T_SELECT)&&!(bits&(1u<<22)))tests=false;
 if((tm&T_TABS)&&!(bits&(1u<<25)))tests=false;
 if(tm&T_MULTISTEP){int before=shadow;if(hasEnterRoute&&sawMutation){shadow+=2;shadow+=3;if(shadow>before+2)bits|=1u<<30;}else tests=false;}
 if(tm&T_COHERENCE){int checkpoint=shadow;if((hasClickable||hasInput)&&sawMutation){shadow+=1;if(shadow==checkpoint+1)bits|=1u<<31;else tests=false;}else tests=false;}
 if(!tests)bits&=~(1u<<8); // executable TESTS failure invalidates normal termination proof
 return bits;
}
static void activate(const RunReq&r){if(!valid(r)){sc(SYS_FORGE_RUN_REPORT,2,1);return;}copyTitle(r.name);appKey=hashName(r.name);codeBytes=r.bytes;for(u32 i=0;i<codeBytes;i++)code[i]=r.code[i];counter=0;for(u32 z=0;z<3;z++){inputLen[z]=0;inputs[z][0]=0;}activeInput=0;for(u32 z=0;z<4;z++)vars[z]=0;compareFlag=false;itemCount=0;loadState();if(!win)win=makeWindow(windowEp,W,H,170,120);active=win!=0;dirty=active;u32 probe=runtimeProbe(r);sc(SYS_FORGE_RUN_REPORT,active?1:2,active?probe:2);}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);serviceEp=(u64)sc(SYS_IPC_CREATE,IPC_RECV);if(!pix||!serviceEp)sc(0,2);u64 pid=(u64)sc(SYS_GETPID);u32 sid=(pid?FORGE_PRIVATE_BASE+(u32)pid:FORGE_RUNNER_SERVICE);if(sc(53,sid,serviceEp)<0)sc(0,3); InstalledPackage ip{}; if(sc(SYS_FORGE_PACKAGE_FETCH,(u64)&ip)==(i64)sizeof(ip)){oneShotInstalled=true;RunReq rq{};rq.magic=0x33434246;rq.bytes=ip.bytes;rq.budget=ip.budget;rq.caps=ip.caps;rq.testMask=0;for(u32 i=0;i<39;i++)rq.name[i]=ip.name[i];for(u32 i=0;i<ip.bytes&&i<128;i++)rq.code[i]=ip.code[i];activate(rq);} for(;;){Wire m{};while(sc(SYS_IPC_RECV,serviceEp,(u64)&m)>0){if(m.type==MSG_RUN&&m.bytes==sizeof(RunReq)){activate(*(RunReq*)m.payload);sc(0,active?0:4);}}if(active&&windowEp){while(sc(SYS_IPC_RECV,windowEp,(u64)&m)>0){if(m.type==KEY&&m.bytes==sizeof(KeyEv)){char c=(char)((KeyEv*)m.payload)->codepoint;u32 ai=activeInput%3;if(c=='\b'){if(inputLen[ai])inputs[ai][--inputLen[ai]]=0;}else if(c=='\t'){activeInput=(activeInput+1)%3;}else if(c=='\n'){u8 action=0;for(u32 ip=0;ip+3<codeBytes;ip+=4){if(code[ip]==OP_EVENT&&code[ip+1]==1)action=code[ip+2];}if(action==1&&inputLen[0]&&itemCount<6){u32 j=0;for(;j<inputLen[0]&&j<63;j++)items[itemCount][j]=inputs[0][j];items[itemCount][j]=0;itemCount++;vars[0]++;}else if(action==2&&inputLen[0]&&itemCount<6){u32 j=0;for(;j<inputLen[0]&&j<40;j++)items[itemCount][j]=inputs[0][j];if(inputLen[1]&&j<62){items[itemCount][j++]=' ';items[itemCount][j++]='-';items[itemCount][j++]=' ';for(u32 k=0;k<inputLen[1]&&j<63;k++)items[itemCount][j++]=inputs[1][k];}items[itemCount][j]=0;itemCount++;vars[0]+=parseInt(inputs[0]);}else if(action==3&&inputLen[0]){vars[0]+=parseInt(inputs[0]);counter=vars[0];}else if(action==4&&inputLen[0]){counter=(int)inputLen[0];}compareFlag=vars[0]>100;for(u32 z=0;z<3;z++){inputLen[z]=0;inputs[z][0]=0;}activeInput=0;saveState();}else if(c>=32&&c<127&&inputLen[ai]<94){inputs[ai][inputLen[ai]++]=c;inputs[ai][inputLen[ai]]=0;}dirty=true;}else if(m.type==POINTER&&m.bytes==sizeof(PtrEv)){auto*q=(PtrEv*)m.payload;if(q->flags&1){for(u32 hi=0;hi<hitCount;hi++){Hit&h=hits[hi];if(!inside(h,q->x,q->y))continue;if(h.op==OP_INPUT){activeInput=h.a?((h.a-1)%3):0;}else if(h.op==OP_BUTTON){if(h.a==1){counter++;vars[0]=counter;}else{counter=0;vars[0]=0;itemCount=0;}}else if(h.op==OP_ACTION){if(h.a==2){counter=0;vars[0]=0;itemCount=0;}else if(inputLen[0]&&itemCount<6){u32 j=0;for(;j<inputLen[0]&&j<63;j++)items[itemCount][j]=inputs[0][j];items[itemCount][j]=0;itemCount++;inputLen[0]=0;inputs[0][0]=0;vars[0]++;}}else if(h.op==OP_CHECKBOX){vars[1]=vars[1]?0:1;}else if(h.op==OP_SELECT){vars[2]=(vars[2]+1)%3;}else if(h.op==OP_NUMBER){activeInput=0;}else if(h.op==OP_TABS){vars[3]=vars[3]?0:1;}compareFlag=vars[0]>100;saveState();dirty=true;break;}}}else if(m.type==CLOSE){active=false;win=0;windowEp=0;if(oneShotInstalled)sc(0,0);}}}if(dirty)draw();sc(SYS_YIELD);}}
